NAME = 'vlsJoNT: Het Nieuwe Testament by Nicolaas De Jonge'
BOOK = 'II Timothy'

CHAPTERS = {
    1: {
        1: 'Paulus, een apostel van Jezus Christus, door den wil van God, naar de belofte des levens dat in Christus Jezus is;',
        2: 'aan Timotheüs, mijn beminden zoon: genade, barmhartigheid, vrede, van God den Vader en van onzen Heere Jezus Christus!',
        3: 'Ik dank God, wien ik dien van mijn voorouders af in een zuivere konsciëntie, gelijk ik onophoudelijk aan u gedachtig ben in mijn gebeden, nacht en dag,',
        4: 'begeerende u te zien, gedachtig zijnde aan uw tranen, opdat ik vervuld moge; worden met blijdschap,',
        5: 'mij in gedachtenis brengende het ongeveinsd geloof dat in u is, dat eerst gewoond heeft in uw grootmoeder Loïs en in uw moeder Eunice; en ik ben overtuigd dat het ook in u is.',
        6: 'Daarom breng ik u in gedachtenis dat gij de genadegifte Gods weder moet opwekken die in u is door de oplegging mijner handen.',
        7: 'Want God heeft ons niet gegeven een geest van vreesachtigheid, maar van kracht en van liefde en van matigheid.',
        8: 'Schaam u dan niet over het getuigenis van onzen Heere, noch over mij, zijn gevangene, maar lijd mede met het Evangelie, naar de kracht van God,',
        9: 'die ons verlost heeft en geroepen met een heilige roeping, niet naar onze werken maar naar zijn eigen voornemen en genade, die ons gegeven is in Christus Jezus vóór de tijden der eeuwen,',
        10: 'doch die nu geopenbaard is door de verschijning van onzen Verlosser Jezus Christus, die den dood heeft krachteloos gemaakt, doch leven en onverderfelijkheid heeft te voorschijn gebracht door het Evangelie,',
        11: 'waartoe ik gesteld ben als een prediker en apostel en leeraar.',
        12: 'Om welke oorzaak ook ik deze dingen lijd, maar ik ben niet beschaamd geworden; want ik weet in wien ik geloofd heb, en ik ben overtuigd dat Hij machtig is te bewaren wat mij toebetrouwd is, tot dien dag.',
        13: 'Houd vast het voorbeeld der gezonde woorden die gij van mij gehoord hebt in geloof en liefde, die in Christus Jezus is.',
        14: 'Bewaar het goede dat u toevertrouwd is, door den Heiligen Geest die in ons woont.',
        15: 'Gij weet dit, dat allen die in Asië zijn van mij afgekeerd zijn, waaronder ook Fygellus en Hermogenes.',
        16: 'De Heere doe barmhartigheid aan het huisgezin van Onesiforus, want dikwijls heeft hij mij verkwikt en zich niet geschaamd over mijn boeien;',
        17: 'maar in Rome gekomen zijnde heeft hij mij weldra gezocht en gevonden;',
        18: 'de Heere geve hem barmhartigheid te vinden bij den Heere in dien dag. En hoezeer hij in Efesus is dienstig geweest, dat weet gij zeer wel.',
    },
    2: {
        1: 'Gij dan, mijn zoon, word gesterkt in de genade die in Christus Jezus is.',
        2: 'En wat gij gehoord hebt van mij door veel getuigen, vertrouw gij dat toe aan getrouwe menschen, die bekwaam zullen zijn ook anderen te onderwijzen.',
        3: 'Lijd mede verdrukking als een goed krijgsknecht van Jezus Christus.',
        4: 'Niemand die in den krijgsdienst is bemoeit zich met de zaken van den leeftocht, opdat hij moge behagen aan dengene die hem tot den krijgsdienst aangenomen heeft.',
        5: 'En ook als iemand strijdt dan wordt hij niet gekroond als hij niet wettelijk gestreden heeft.',
        6: 'De landman die arbeidt moet het eerst van de vruchten genieten.',
        7: 'Let wel op hetgeen ik zeg; want de Heere zal u verstand geven in alles.',
        8: 'Houd in gedachtenis Jezus Christus, verrezen uit de dooden, uit de nakomelingschap van David, volgens mijn Evangelie,',
        9: 'waarin ik verdrukking lijd tot de boeien toe, als een kwaaddoener, maar het woord Gods wordt niet gebonden.',
        10: 'Daarom verdraag ik alles om de uitverkorenen, opdat ook zij de zaligheid bekomen zouden, die is in Christus Jezus, met eeuwige glorie.',
        11: 'Waarachtig is het woord: want als wij mede gestorven zijn, zullen wij ook mede leven;',
        12: 'als wij verdragen, dan zullen wij ook mede als koningen heerschen; als wij Hem verloochenen, dan zal Hij ons ook verloochenen;',
        13: 'als wij ontrouw zijn, Hij blijft getrouw, want Hij kan zichzelven niet verloochenen.',
        14: 'Breng deze dingen in gedachtenis, hen betuigende voor het aangezicht van God dat zij geen woordenstrijd voeren, dat tot niets dient, en tot nadeel is der hoorders.',
        15: 'Benaarstig u om u zelven beproefd voor God te stellen, als een arbeider die; zich niet moet schamen, die het woord der waarheid recht snijdt.',
        16: 'Doch stel u tegen de goddelooze ijdele klapperijen, want zij zullen meer en meer: toenemen in goddeloosheid,',
        17: 'en hun woord zal voort eten als een kanker; van dezen zijn Hymeneüs en Filetus,',
        18: 'die van de waarheid zijn afgevallen, zeggende dat de verrijzenis al geschied is en die het geloof van sommigen ondermijnen.',
        19: 'Toch staat het vaste fundament Gods, dat dit zegel heeft de Heere kent degenen die van Hem zijn; en ook dit dat hij afstand doe van onrechtvaardigheid, al wie den Naam des Heeren belijdt.',
        20: 'Doch in een groot huis zijn niet alleen vaten van goud en van zilver, maar ook van hout en van aarde, en sommigen zijn tot versiering maar anderen tot ontsiering.',
        21: 'Als dan iemand zich zelven van die dingen gezuiverd heeft dan zal hij zijn een vat tot versiering, geheiligd, dienstig voor den meester, tot alle goed werk geschikt.',
        22: 'Maar vlied de lusten der jonkheid, en tracht naar rechtvaardigheid, vertrouwen, liefde, vrede met degenen die den Heer aanroepen uit een zuiver hart.',
        23: 'Maar dwaze en onleerzame vraagstukken moet gij verwerpen, wetende dat zij twistingen voortbrengen.',
        24: 'Doch een dienstknecht des Heeren moet niet twisten maar vriendelijk zijn jegens allen, bekwaam om te onderwijzen, verdraagzaam,',
        25: 'in zachtmoedigheid onderwijzende degenen die tegenstaan, of wellicht God hun te eenigertijd boetvaardigheid mocht geven tot kennis der waarheid,',
        26: 'en zij wederom wakker mochten worden uit den strik des duivels, onder wien zij gevangen waren tot zijn wil.',
    },
    3: {
        1: 'Doch gij moet dat weten dat er in de laatste dagen moeilijke tijden zullen komen.',
        2: 'Want de menschen zullen zijn zelfzuchtig, geldgierig, grootsprekers, hoovaardig, lasteraars, den ouders ongehoorzaam, ondankbaar, onheilig,',
        3: 'zonder natuurlijke liefde, onverzoenlijk, oproerig, onmatig, wreed, zonder liefde voor het goede,',
        4: 'verraders, opgewonden, opgeblazen, meer liefhebbers van wellusten dan liefhebbers van God,',
        5: 'wel den vorm houdende van godvruchtigheid maar de kracht van deze verloochenende. Keer u ook af van dezen.',
        6: 'Want uit dezen zijn zij die insluipen in de huizen en de vrouwkens gevangen nemen die met zonden beladen zijn, gedreven wordende door velerlei begeerlijkheden,',
        7: 'altijd leerende en nooit tot kennis der waarheid kunnende komen.',
        8: 'En op dezelfde wijze als Jannes en Jambres aan Mozes tegenstonden, zoo staan ook dezen de waarheid tegen menschen, verdorven van verstand, verwerpelijk wat het geloof betreft.',
        9: 'Maar zij zullen niet verder voortgaan, want hun onverstand zal voor allen openbaar zijn, gelijk ook dat van die Jannes en Jambres geweest is.',
        10: 'Doch gij hebt achtervolgd mijn onderwijs, omgang, inzicht, geloof, lankmoedigheid, liefde, volharding,',
        11: 'vervolgingen, smarten, hetgeen mij overkomen is in Antiochië, in Ikoniüm, in Lystre; hoedanige vervolgingen ik doorgestaan heb; en uit die allen heeft de Heer mij verlost.',
        12: 'En allen die godvruchtig willen leven in Christus Jezus, die zullen vervolgd worden.',
        13: 'Doch ondeugende menschen en verleiders zullen tot erger voortgaan, dwalende en tot dwaling vervoerende.',
        14: 'Maar blijf gij in de dingen die gij geleerd hebt en waarvan gij verzekerd zijt, wetende van wien gij ze geleerd hebt,',
        15: 'en dat gij van kinds af de Heilige Schriften hebt geweten die u kunnen onder wijzen tot behoudenis door het geloof dat in Christus Jezus is.',
        16: 'Alle Schriftuur is van God ingegeven en dienstig tot onderwijzing, tot bestraffing, tot verbetering, tot opvoeding die in de rechtvaardigheid is',
        17: 'opdat de mensch Gods volkomen moge zijn, tot alle goed werk volkomen bereid.',
    },
    4: {
        1: 'Ik betuig voor het aangezicht van God en van Jezus Christus, die levenden en dooden oordeelen zal, en bij zijn verschijning en zijn koninkrijk;',
        2: 'predik het woord, dring het aan tijdig en ontijdig, bestraf, vermaan, berisp in alle zachtmoedigheid en onderwijzing.',
        3: 'Want er zal een tijd zijn dat zij het gezonde onderwijs niet zullen verdragen, maar naar hun eigen begeerten zullen zij voor zich zelven onderwijzers verzamelen, daar zij belust zijn op het hooren van streelende dingen.',
        4: 'En zij zullen het gehoor afkeeren van de waarheid, en zullen zich keeren tot fabelen.',
        5: 'Maar gij, wees waakzaam in alles, verdraag het kwade, doe het werk van een evangelist, volbreng uw dienstwerk.',
        6: 'Want ik word al geofferd en de tijd mijner losmaking is op handen.',
        7: 'Den goeden strijd heb ik gestreden, den loop heb ik volbracht, het geloof heb ik bewaard.',
        8: 'Voorts is voor mij weggelegd de kroon der rechtvaardigheid, die mij de Heere in dien dag geven zal, de rechtvaardige Rechter, doch niet alleen aan mij maar ook aan allen die zijn verschijning hebben bemind.',
        9: 'Spoed u om haast tot mij te komen.',
        10: 'Want Demas heeft mij verlaten, uit liefde tot de tegenwoordige eeuw, en is gereisd naar Thessalonika, Krescens naar Galatië, Titus naar Dalmatië.',
        11: 'Lukas is alleen met mij. Neem Markus en breng hem met u, want hij is mij zeer nuttig tot het dienstwerk.',
        12: 'Tychikus heb ik gezonden naar Efesus.',
        13: 'Den mantel, dien ik in Troas heb gelaten bij Karpus, breng dien mede als gij komt; ook de boeken, vooral de perkamenten.',
        14: 'Alexander de koperslager heeft mij veel kwaad toegebracht; de Heere zal hem loon geven naar zijn werken.',
        15: 'Voor dezen moet gij u ook wachten, want hij heeft onze woorden zeer tegengestaan.',
        16: 'In mijn eerste verdediging heeft niemand mij bijgestaan, maar zij hebben mij allen verlaten. Het moge hun niet toegerekend worden!',
        17: 'Doch de Heere heeft mij bijgestaan en bekrachtigd, opdat door mij de prediking volkomen zou worden, en al de heidenen ze hooren zouden; en ik ben verlost uit den muil van den leeuw.',
        18: 'De Heere zal mij verlossen van alle kwaad werk en zal mij bewaren tot zijn hemelsch koninkrijk. Hem zij de glorie tot in alle eeuwigheid! Amen.',
        19: 'Groet Priska en Aquila en het huisgezin van Onesiforus.',
        20: 'Erastus is in Korinthe gebleven, doch Trofimus heb ik krank in Milete gelaten.',
        21: 'Spoed u om vóór den winter te komen. U groeten Eubulus, en Pudens, en Linus, en Klaudia, en al de broeders.',
        22: 'De Heere Jezus Christus zij met uw geest. De genade met ulieden! Amen.',
    },
}
